import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    t = int(input_data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(input_data[idx])
        m = int(input_data[idx+1])
        idx += 2

        grid = []
        for r in range(n):
            row = []
            for c in range(m):
                row.append(int(input_data[idx]))
                idx += 1
            grid.append(row)

        bad_cols = []
        for r in range(n):
            for c in range(1, m):
                if grid[r][c] < grid[r][c-1]:
                    bad_cols.append((r, c-1, c))

        if not bad_cols:
            results.append("1 1")
            continue

        if len(bad_cols) > 2:
            results.append("-1")
            continue

        candidates = set()
        for r, c1, c2 in bad_cols:
            candidates.add(c1)
            candidates.add(c2)

        if len(candidates) > 2:
            results.append("-1")
            continue
        elif len(candidates) == 1:
            c1 = list(candidates)[0]
            results.append(f"{c1+1} {c1+1}")
            continue
        else:
            c_list = sorted(list(candidates))
            c1, c2 = c_list[0], c_list[1]

            def check_grid(cols_to_swap):
                if cols_to_swap[0] == cols_to_swap[1]:
                    return True
                for r in range(n):
                    v1 = grid[r][cols_to_swap[0]]
                    v2 = grid[r][cols_to_swap[1]]

                    prev = -1
                    for c in range(m):
                        val = grid[r][c]
                        if c == cols_to_swap[0]:
                            val = v2
                        elif c == cols_to_swap[1]:
                            val = v1

                        if c > 0 and val < prev:
                            return False
                        prev = val
                    # Check the boundary between the swapped columns if they are adjacent
                    # Actually the loop above handles it, but let's double check logic
                    # The loop constructs the row virtually.
                    # However, constructing the whole row for every check is O(N*M) which is fine since we only do it twice.
                return True

            if check_grid((c1, c2)):
                results.append(f"{c1+1} {c2+1}")
            elif check_grid((c2, c1)):
                results.append(f"{c2+1} {c1+1}")
            else:
                results.append("-1")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
